fn digit_sum(s: Str) -> Int {
    let mut sum = 0
    let mut digits = 0
    for c in chars(s) {
        if c >= "0" && c <= "9" {
            sum = sum + c.parse_int()?
            digits = digits + 1
        }
    }
    sum
}

